class BoyerMooreSearch:
    MATCH_FOUND = 0
    MISMATCH_FOUND = 1

    def __init__(self, text, pattern):
        self._text = text
        self._pattern = pattern
        self._textLen = len(text)
        self._patLen = len(pattern)

    def get_text(self):
        return self._text

    def get_pattern(self):
        return self._pattern

    def get_text_len(self):
        return self._textLen

    def get_pat_len(self):
        return self._patLen

    def __len_pattern(self):
        return self._patLen

    def match_in_pattern(self, char):
        for i in range(self.__len_pattern() - 1, -1, -1):
            if char == self._pattern[i]:
                return i
        return -1

    def mismatch_in_text(self, currentPos):
        for i in range(self.__len_pattern() - 1, -1, -1):
            if self._pattern[i] != self._text[currentPos + i]:
                return currentPos + i
        return -1

    def find_matches(self):
        positions = self.get_matched_positions()
        return positions

    def get_matched_positions(self):
        positions = []
        num_iterations = self._textLen - self._patLen + 1
        for i in range(num_iterations):
            self.process_position(i, positions)
        return positions

    def process_position(self, i, positions):
        mismatch_index = self.mismatch_in_text(i)
        if mismatch_index == -1:
            positions.append(i)
        else:
            self.handle_mismatch(i, mismatch_index, positions)

    def handle_mismatch(self, i, mismatch_index, positions):
        match_index = self.match_in_pattern(self._text[mismatch_index])
        i = (mismatch_index - match_index)
